    "id": "scraped-848968301161",
    "company": "Network of Ethiopian Women’s Associations (NEWA)",
    "source": "EthioJobs",
    "title": "CALL FOR PAPERS: From Representation to Influence: Advancing Women’s Leadership and Decision-Making in Ethiopia’s Post-Election Context",
    "location": "Addis Ababa",
    "mode": "Onsite",
    "type": "Full-time Entry Level",
    "experience": "0-2 Years",
